import "./top-bar-menu.scss";

import { Button } from "@optimizely/axiom";
import { Component, HTMLProps, ReactElement } from "react";

interface TopBarMenuProps {
    icon: ReactElement<HTMLProps<HTMLOrSVGElement>> | string;
    open: boolean;
    onOpen: () => void;
    onClose: () => void;
    tooltip?: string;
}

export class TopBarMenu extends Component<TopBarMenuProps> {
    static defaultProps = {
        open: false,
        onOpen: () => null,
        onClose: () => null,
    };

    render(): ReactElement {
        return (
            <Button className="epi-global-notification-menu" onClick={this.props.onOpen} title={this.props.tooltip}>
                {this.props.icon}
            </Button>
        );
    }
}
