import { BlockList, Button, Dropdown, Link } from "@optimizely/axiom";
import { Fragment } from "react";

import { getCmsUiIcon } from "./getCmsUiIcon.tsx";
import { GlobalNotification } from "./global-notification/global-notification.tsx";
import { MenuItem } from "./navigation.types.ts";
import { NavigationPaths } from "./navigation-constants.ts";
import { onNavigate } from "./onNavigate.tsx";
import { SearchMenu } from "./search-menu/search-menu.tsx";

interface NavigationMenuItemProps {
    actionItem: MenuItem;
    index: number;
    viewModeUrl: string;
    shellUrl?: string;
    searchProvidersUrl: string;
    currentCulture?: string;
    currentUiCulture?: string;
    searchUrl: string;
}

function NavigationMenuItem({
    actionItem,
    index,
    viewModeUrl,
    currentCulture,
    currentUiCulture,
    searchProvidersUrl,
    shellUrl,
    searchUrl,
}: NavigationMenuItemProps) {
    if (actionItem.path === NavigationPaths.GLOBAL_SITES) {
        return <Fragment key={index} />;
    }

    if (actionItem.path === NavigationPaths.GLOBAL_SEARCH) {
        return (
            <SearchMenu
                key={index}
                searchUrl={searchUrl}
                searchProvidersUrl={searchProvidersUrl}
                tooltip={actionItem.tooltip}
                shellUrl={shellUrl || ""}
            />
        );
    }

    if (actionItem.path === NavigationPaths.GLOBAL_NOTIFICATION) {
        return (
            <GlobalNotification
                key={index}
                tooltip={actionItem.tooltip}
                storeUrl={actionItem.url}
                cultureName={currentCulture || ""}
                uiCultureName={currentUiCulture || ""}
            />
        );
    }

    const icon = getCmsUiIcon(actionItem);
    if (icon) {
        if (actionItem.children && actionItem.children.length > 0) {
            return (
                <Dropdown
                    key={index}
                    buttonContent={
                        <div className="flex flex-align--center">
                            <span className="flex">{icon}</span>
                        </div>
                    }
                    title={actionItem.tooltip}
                >
                    <BlockList>
                        {actionItem.children.map((item) => (
                            <BlockList.Category key={item.name}>
                                <BlockList.Item>
                                    <div title={item.tooltip}>
                                        <Link
                                            href={item.url}
                                            rightIcon={item.target === "_blank" ? "arrow-up-right-from-square" : ""}
                                            newWindow={item.target === "_blank"}
                                        >
                                            {item.name}
                                        </Link>
                                    </div>
                                </BlockList.Item>
                            </BlockList.Category>
                        ))}
                    </BlockList>
                </Dropdown>
            );
        } else {
            let actionUrl = actionItem.url;
            if (actionItem.path === NavigationPaths.GLOBAL_SITES) {
                actionUrl = viewModeUrl || actionUrl;
            }

            return (
                <div className="epi-uif-menu-anchor mdc-menu-surface--anchor" key={index}>
                    <Button
                        style="unstyled"
                        title={actionItem.tooltip}
                        className="mdc-top-app-bar__action-item mdc-icon-button epi-uif-interactive-icon epi-interactive-icon"
                    >
                        <div title={actionItem.tooltip}>
                            <Link
                                key={index}
                                href={actionUrl}
                                isDisabled={false}
                                style="reverse"
                                newWindow={actionItem.target === "_blank"}
                            >
                                {icon}
                            </Link>
                        </div>
                    </Button>
                </div>
            );
        }
    }

    if (actionItem.children && actionItem.children.length > 0) {
        // The Design System guidelines designate that icons should be used for action items, but we have to support text labels in CMS UI until there are icons partners can use.
        return (
            <Dropdown buttonContent={actionItem.name} arrowIcon={"down"} title={actionItem.tooltip} key={index}>
                <BlockList>
                    {actionItem.children.map((item) => (
                        <BlockList.Category key={item.name}>
                            <BlockList.Item onClick={(evt: React.MouseEvent) => onNavigate(item, undefined, evt)}>
                                <div className="flex flex-align--center" title={item.tooltip}>
                                    <div className="flex--1">
                                        <div>{item.name}</div>
                                    </div>
                                </div>
                            </BlockList.Item>
                        </BlockList.Category>
                    ))}
                </BlockList>
            </Dropdown>
        );
    }

    return (
        <a
            key={index}
            className="text-action-item"
            href={actionItem.url}
            target={actionItem.target}
            title={actionItem.tooltip}
        >
            {actionItem.name}
        </a>
    );
}

interface ActionMenuItemsProps {
    viewModeUrl: string;
    actionItems: MenuItem[];
    shellUrl?: string;
    searchProvidersUrl: string;
    currentCulture?: string;
    currentUiCulture?: string;
    searchUrl: string;
}

export function ActionMenuItems({
    viewModeUrl,
    actionItems,
    currentCulture,
    currentUiCulture,
    searchProvidersUrl,
    searchUrl,
    shellUrl,
}: ActionMenuItemsProps) {
    return actionItems.map((actionItem, index) => (
        <NavigationMenuItem
            actionItem={actionItem}
            index={index}
            viewModeUrl={viewModeUrl}
            currentCulture={currentCulture}
            currentUiCulture={currentUiCulture}
            searchProvidersUrl={searchProvidersUrl}
            searchUrl={searchUrl}
            shellUrl={shellUrl}
        />
    ));
}
