import { Feedback } from "@optimizely/axiom";

import { useUserFeedback } from "./useUserFeedback";

export const CentralUserFeedback = () => {
    const { message, setMessage } = useUserFeedback();

    return (
        <Feedback
            className="user-feedback"
            onClose={() => setMessage({ text: "", isError: false })}
            open={!!message.text}
            type={message.isError ? "bad-news" : "good-news"}
        >
            {message.text}
        </Feedback>
    );
};
