import "./search-menu.scss";

import { resources } from "@episerver/shared/resources";
import { Icon, Input, Sidebar, Toolbar, Typography } from "@optimizely/axiom";
import axios from "axios";
import { FormEvent, FunctionComponent, useRef, useState } from "react";
import OutsideClickHandler from "react-outside-click-handler";

import { TopBarMenu } from "../top-bar-menu/top-bar-menu";
import { SearchProvider, SearchProviderResult, SearchResult } from "./search-provider-results";

interface SearchMenuProps {
    searchProvidersUrl: string;
    searchUrl: string;
    tooltip?: string;
    shellUrl: string;
}

export const SearchMenu: FunctionComponent<SearchMenuProps> = (props) => {
    const [searchText, setSearchText] = useState("");
    const [searchProviders, setSearchProviders] = useState<SearchProvider[] | null>(null);
    const [results, setResults] = useState<{ [K: string]: SearchResult[] } | null>(null);
    const inputRef = useRef<HTMLInputElement>(null);
    const [isOpen, setIsOpen] = useState<boolean>(false);

    const getSearchProviders = () => {
        return new Promise<SearchProvider[]>((resolve) => {
            if (searchProviders !== null) {
                resolve(searchProviders);
            }

            axios.get(props.searchProvidersUrl).then((result) => {
                setSearchProviders(result.data.searchProviders);
                resolve(result.data.searchProviders);
            });
        });
    };

    const searchWithProviders = async () => {
        if ((searchText || "").trim()) {
            const providers = await getSearchProviders();
            Promise.all(
                providers.map((searchProvider) => {
                    return axios
                        .get(props.searchUrl + "/" + searchProvider.id, {
                            params: {
                                epiSearchQuery: searchText.trim(),
                                parameters: JSON.stringify({ global: true }),
                            },
                        })
                        .catch((err) => {
                            console.error("Unable to find search provider: " + err);
                        });
                }),
            ).then((values) => {
                const resultObject: { [K: string]: SearchResult[] } = {};
                values.forEach((value) => {
                    if (value) {
                        const result = value.data.searchResult;
                        if (result && result.length > 0) {
                            resultObject[value.data.providerId] = result;
                        }
                    }
                });
                setResults(resultObject);
            });
        }
    };

    const onSearchSubmit = (event: FormEvent): void => {
        event.preventDefault();
        setResults(null);
        searchWithProviders();
        setSearchText(searchText);
    };

    const handleClickOutside = () => {
        if (!isOpen) {
            return;
        }
        setIsOpen(false);
    };

    return (
        <OutsideClickHandler onOutsideClick={handleClickOutside}>
            <div className="epi-global-search-menu epi-global-notification">
                <TopBarMenu
                    icon={<Icon name="search" size="small" />}
                    open={!isOpen}
                    onOpen={() => {
                        setIsOpen(!isOpen);
                        const inputEl = inputRef.current;
                        if (inputEl) {
                            setTimeout(() => {
                                inputEl.focus();
                            }, 0);
                        }
                    }}
                    tooltip={props.tooltip}
                />
                <Sidebar
                    className={"epi-global-search-menu__list " + (isOpen ? "open" : "close")}
                    boxShadow={true}
                    isOpen={isOpen}
                    border={true}
                    isResizable={true}
                    sticky={true}
                >
                    <div className="epi-global-search-menu__list__inner">
                        <div className="epi-global-search-menu__list__inner__close-icon" onClick={handleClickOutside}>
                            <Icon name="xmark" size="large" />
                        </div>
                        <div className="epi-global-search-menu__list__inner__header">
                            <Toolbar toolbarStyle={["bare"]}>
                                <Toolbar.Left>
                                    <Typography type="header3" tag="span">
                                        {resources.episerver.shell.ui.views.search.resources.labelsearchtext}
                                    </Typography>
                                </Toolbar.Left>
                            </Toolbar>
                        </div>
                        <form onSubmit={onSearchSubmit} className="epi-global-search-menu__list__inner__search-field">
                            <Input
                                leftIconName="search"
                                displayError={false}
                                isFilter={false}
                                placeholder={resources.episerver.shell.ui.views.search.resources.labelsearchtext}
                                type="text"
                                value={searchText}
                                onChange={(e) => setSearchText(e.currentTarget.value)}
                                hasClearButton={!!searchText}
                                onClearButtonClick={() => {
                                    setSearchText("");
                                    setResults(null);
                                }}
                            />
                        </form>
                        {!searchProviders || searchProviders.length === 0 || searchText === "" ? null : (
                            <div className="epi-global-search-menu__list__inner__search-result">
                                {results === null || Object.keys(results).length > 0 ? (
                                    searchProviders.map((searchProvider) => (
                                        <SearchProviderResult
                                            key={searchProvider.id}
                                            onItemClick={() => setIsOpen(false)}
                                            searchUrl={props.searchUrl}
                                            provider={searchProvider}
                                            results={(results && results[searchProvider.id]) || []}
                                            searchTerm={searchText}
                                        />
                                    ))
                                ) : (
                                    <Typography
                                        type="header5"
                                        tag="span"
                                        className="epi-global-search-menu__list__inner__search-result__empty"
                                    >
                                        {resources.episerver.shell.ui.views.search.resources.noresultmessage}
                                    </Typography>
                                )}
                            </div>
                        )}
                    </div>
                </Sidebar>
            </div>
        </OutsideClickHandler>
    );
};
