import { commonSettings } from "@episerver/shared/common-settings";
import axios, { AxiosRequestHeaders } from "axios";

export const isFetchHeaders = (obj: any): obj is Headers => {
    return obj && typeof obj.set === "function" && typeof obj.append === "function";
};
export const setVerificationToken = (
    headers: AxiosRequestHeaders | Headers | Record<string, string> = axios.defaults
        .headers as unknown as AxiosRequestHeaders,
) => {
    if (!headers) {
        return;
    }

    if (commonSettings.antiforgeryHeaderName && commonSettings.antiforgeryHeaderValue) {
        if (isFetchHeaders(headers)) {
            headers.set(commonSettings.antiforgeryHeaderName, commonSettings.antiforgeryHeaderValue);
        } else {
            (headers as AxiosRequestHeaders)[commonSettings.antiforgeryHeaderName] =
                commonSettings.antiforgeryHeaderValue;
        }
    }
};

export function getCommonHeaders(): Record<string, string> {
    const result: Record<string, string> = {};
    if (commonSettings.antiforgeryHeaderName && commonSettings.antiforgeryHeaderValue) {
        result[commonSettings.antiforgeryHeaderName] = commonSettings.antiforgeryHeaderValue;
    }
    return result;
}
