import "./axios-config";
import "./navigation.scss";

import { Link } from "@optimizely/axiom";
import lightBrandLogoUrl from "@optimizely/design-tokens/dist/brand-assets/brand-logo-white.svg";
import { createPortal } from "react-dom";
import { createRoot } from "react-dom/client";

import { CentralUserFeedback } from "./CentralUserFeedback";
import { ActionMenuItems } from "./navigation-menu-item.tsx";
import { observe } from "./navigationObserver";
import parseNavigationRoot from "./parse-navigation-root.ts";
import { ProductDropdown } from "./product-dropdown.tsx";
import { SideBarNavigation } from "./side-bar-navigation/side-bar-navigation";
import { useMenuItems } from "./useMenuItems.tsx";

const {
    searchUrl,
    searchProvidersUrl,
    navigationUrl,
    productsUrl,
    contentLanguage,
    currentCulture,
    currentProductId,
    currentUiCulture,
    parentProductId,
    shellUrl,
    sideBarNavigationRoot,
    root,
} = parseNavigationRoot;

const CmsNavigation = () => {
    const {
        navigationItems,
        setNavigationItems,
        actionItems,
        levelOne,
        levelTwo,
        onMenuSelected,
        isActive,
        viewModeUrl,
    } = useMenuItems(navigationUrl, contentLanguage);

    return (
        <>
            <header className="epi-pn-navigation mdc-top-app-bar mdc-top-app-bar--fixed mdc-top-app-bar--dense">
                <div className="epi-pn-navigation-row__primary mdc-top-app-bar__row">
                    <section className="mdc-top-app-bar__section mdc-top-app-bar__section--align-start">
                        <div className="epi-pn-logo-background" />
                        <div className="axiom-navigation__logo">
                            <Link testSection="navigation--brand-logo">
                                <img
                                    alt="logo"
                                    src={lightBrandLogoUrl}
                                    className="push--right axiom-navigation__logo--mark"
                                />
                            </Link>
                        </div>
                        <div className="axiom-navigation__title">{"Optimizely"}</div>
                    </section>
                    <section className="epi-pn-navigation__section--align-center mdc-top-app-bar__section">
                        <ProductDropdown
                            setNavigationItems={setNavigationItems}
                            currentProductId={currentProductId}
                            productsUrl={productsUrl}
                            parentProductId={parentProductId}
                        />
                    </section>
                    <section className="mdc-top-app-bar__section mdc-top-app-bar__section--align-end">
                        <ActionMenuItems
                            actionItems={actionItems}
                            viewModeUrl={viewModeUrl}
                            searchUrl={searchUrl}
                            searchProvidersUrl={searchProvidersUrl}
                            shellUrl={shellUrl}
                            currentUiCulture={currentUiCulture}
                            currentCulture={currentCulture}
                        />
                    </section>
                </div>
            </header>
            <CentralUserFeedback />
            {sideBarNavigationRoot &&
                createPortal(
                    <SideBarNavigation
                        menuItems={navigationItems}
                        onItemSelect={onMenuSelected}
                        levelOne={levelOne}
                        levelTwo={levelTwo}
                        isActive={isActive}
                    />,
                    sideBarNavigationRoot,
                )}
        </>
    );
};

observe(root);
const reactRoot = createRoot(root);
reactRoot.render(<CmsNavigation />);
