import { setVerificationToken } from "@episerver/shared/helpers/verification-token-setter";

const root = document.getElementById("epi-navigation-root");

if (!root) {
    throw new Error("No `epi-navigation-root` element found.");
}

const sideBarNavigationRoot = document.createElement("div");
sideBarNavigationRoot.setAttribute("id", "sideBarNavigationRoot");
document.body.insertBefore(sideBarNavigationRoot, document.body.firstElementChild);
// HACK: move the navigation to the start of the body in order
// to avoid doing a breaking change in older WebForm views.
document.body.insertBefore(root, document.body.firstElementChild);

const shellUrl = root.dataset.epiShellUrl;
const contentLanguage = root.dataset.epiContentLanguage;
const currentProductId = root.dataset.epiProductId;
const parentProductId = root.dataset.epiParentProduct;
const currentUiCulture = root.dataset.epiCurrentUiCulture;
const currentCulture = root.dataset.epiCurrentCulture;
const productsUrl = `${shellUrl}epiproducts`;
const navigationUrl = `${shellUrl}epiplatformnavigation?product=${currentProductId}&parentProduct=${parentProductId}`;
const searchProvidersUrl = `${shellUrl}epiplatformnavigationsearchproviders`;
const searchUrl = `${shellUrl}episearch/search`;

// set antiforgery header
setVerificationToken();

const navigationRoot = {
    sideBarNavigationRoot,
    root,
    shellUrl,
    contentLanguage,
    currentProductId,
    parentProductId,
    currentUiCulture,
    currentCulture,
    productsUrl,
    navigationUrl,
    searchProvidersUrl,
    searchUrl,
};

export default navigationRoot;
