import { resources } from "@episerver/shared/resources";
import { BlockList, Icon, Typography } from "@optimizely/axiom";
import { FunctionComponent } from "react";

import { formatDateWithDistanceToNow } from "../locale.ts";
import { GlobalNotificationListProps } from "./global-notification.d";

export const GlobalNotificationList: FunctionComponent<GlobalNotificationListProps> = (props) => {
    return (
        <>
            {props.items?.length === 0 ? (
                <Typography type="header4" tag="span" className="epi-global-notification-list-result-empty">
                    {resources.episerver.cms.notification.list.nodatamessage}
                </Typography>
            ) : (
                <BlockList hasBorder={false} className="epi-global-notification-list-result">
                    {props.items.map((x) => (
                        <BlockList.Item onClick={() => props.onItemClick(x)} key={x.id}>
                            <div className="flex flex-align--center">
                                <Icon
                                    name="circle-small-solid"
                                    size="small"
                                    color="colors.bandBlueDark"
                                    className={x.hasRead ? "hidden" : ""}
                                />
                                <div className="flex--1">
                                    <Typography type={x.hasRead ? "body" : "subhead"} tag="span">
                                        {x.subject}
                                    </Typography>
                                    <div className="muted" dangerouslySetInnerHTML={{ __html: x.content }} />
                                    <div className="muted micro">
                                        {formatDateWithDistanceToNow(x.posted, props.cultureName, props.uiCultureName)}
                                    </div>
                                </div>
                            </div>
                        </BlockList.Item>
                    ))}
                </BlockList>
            )}
        </>
    );
};
