import { MenuItem } from "../navigation.types";

export function normalizeUrl(url?: string, hash?: string) {
    let match = url || "/";

    // If the URL starts with http, we should parse it as a URL and get the pathname.
    // For cross-origin URLs (e.g. a different CMS instance or an external site), return the
    // full URL unchanged so it can never accidentally match a local pathname.
    if (url?.startsWith("http") && url) {
        try {
            const parsed = new URL(url);
            if (parsed.origin !== window.location.origin) {
                return url;
            }
            match = parsed.pathname;
        } catch {
            // noop
        }
    }

    if (hash) {
        match += hash;
    }

    match = match
        .toLocaleLowerCase()
        .replace(/#\//, "/") // Replace valid #/ hash-route patterns with /
        .replace(/#.*$/, "") // Strip any remaining hash fragments (e.g. #context=something)
        .replace(/\/+/g, "/"); // Replace multiple slashes with a single slash

    if (!match.startsWith("/")) {
        match = "/" + match;
    }

    // The trailing slash is added to avoid matching /ui/cms with /ui/cms-content, for example.
    if (!match.endsWith("/")) {
        match = match + "/";
    }

    return match;
}

export function isMatchUrl(menuItem: MenuItem, path?: string, hash?: string): boolean {
    if (!menuItem?.url) {
        return false;
    }

    // Try-match against the full path and hash.
    return normalizeUrl(path, hash) === normalizeUrl(menuItem.url);
}
